import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";
import { COLORS, LOG_COLORS } from "../constants";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { StatusSystem } from "./systems/status";
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { EventBus } from "./events/EventBus";
import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

// Constants
export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;

    // Time & Speed Control
    public timeScale: number = 1.0;
    public targetTimeScale: number = 1.0; 

    public battleTime: number = 0;
    public mapVersion: number = 0; 

    // Finishing Sequence State
    public isFinishing: boolean = false;
    public victoryTimer: number = 0;
    public winningTeam: Team | null = null;

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public logs: LogEntry[] = [];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    // AI Director State
    public directorTargetId: string | null = null;
    private directorTimer: number = 0;

    public agentMap: Map<number, Agent> = new Map();

    public movement: MovementSystem;
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public ai: AISystem;
    public agentManager: AgentManager;

    constructor() {
        this.movement = new MovementSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.battleTime = 0;
            this.logs = [];
            this.isFinishing = false;
            this.winningTeam = null;
            this.targetTimeScale = 1.0;
            this.timeScale = 1.0;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.isFinishing = false;
        this.winningTeam = null;
        this.targetTimeScale = 1.0;
        this.timeScale = 1.0;
        this.agentMap.clear();

        // 1. Reset Agents
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        // 2. Logic Cleanup
        this.events = []; 
        this.combat.reset(); 

        // 3. Visual Deep Cleanup (CRITICAL)
        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); // Clear cached zones
            this.renderer.vfx.reset();  // Clear all particles immediately
        }

        this.battleTime = 0;
        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();

        this.combat.reset(); 
        this.events = [];

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }

        this.logs = [];
        this.directorTargetId = null;

        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 

        this.bus.emit('GAME_CLEAR', {});
    }

    tick(dt: number) {
        if (!this.isRunning) return;

        if (Math.abs(this.targetTimeScale - this.timeScale) > 0.01) {
            this.timeScale += (this.targetTimeScale - this.timeScale) * 5.0 * dt; 
        } else {
            this.timeScale = this.targetTimeScale;
        }

        this.events.length = 0;
        this.updateDirector(dt);

        if (this.isFinishing) {
            this.victoryTimer -= dt;
            this.updateEntities(dt);

            if (this.victoryTimer <= 0) {
                this.stop();
                this.targetTimeScale = 1.0;
                this.timeScale = 1.0;
                this.bus.emit('GAME_OVER', { winner: this.winningTeam });
            }
            return;
        }

        let blue = 0, red = 0;
        for (const a of this.agents) {
            if (a.hp > 0) a.team === Team.BLUE ? blue++ : red++;
        }

        if ((blue === 0 && red > 0) || (red === 0 && blue > 0)) { 
            this.isFinishing = true;
            this.winningTeam = blue === 0 ? Team.RED : Team.BLUE;
            this.victoryTimer = VICTORY_PHASE_DURATION; 
            this.targetTimeScale = 0.4; 
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;
            this.movement.updatePhysics(a, dt, this);
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.status.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
    }

    private updateDirector(dt: number) {
        this.directorTimer -= dt;
        if (this.directorTargetId) {
            const current = this.agents.find(a => a.id === this.directorTargetId);
            if (!current || current.hp <= 0) {
                this.directorTimer = -1;
            }
        }

        if (this.directorTimer <= 0) {
            let candidates: Agent[] = [];
            let ultCasters: Agent[] = [];

            for (const a of this.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    if (a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT') {
                        ultCasters.push(a);
                    }
                }
            }

            if (candidates.length > 0) {
                if (ultCasters.length > 0) {
                     this.directorTargetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.directorTimer = 4.0; 
                } else {
                     this.directorTargetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     this.directorTimer = 3.0;
                }
            }
        }
    }

    performCast(a: Agent, i: number): NodeState {
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = i;
            a.castTimer = a.skills[i]!.cast;
            a.castingAnimationTimer = a.skills[i]!.cast; 
            a.btStatus = `詠唱 ${a.skills[i]!.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            this.log(a, 'CAST', '詠唱', targetName, `開始引導 ${a.skills[i]!.name} (需 ${a.skills[i]!.cast} 秒)`);
            this.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: a.skills[i]! });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, this.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        const time = this.battleTime.toFixed(1);
        let color = LOG_COLORS.SYSTEM;

        switch(type) {
            case 'MOVE': color = LOG_COLORS.MOVE; break;
            case 'CAST': color = LOG_COLORS.CAST; break;
            case 'HIT': color = LOG_COLORS.HIT; break;
            case 'HEAL': color = LOG_COLORS.HEAL; break;
            case 'DECISION': color = LOG_COLORS.DECISION; break;
            case 'DEATH': color = LOG_COLORS.DEATH; break;
            case 'CC': color = LOG_COLORS.CC; break;
            default: color = LOG_COLORS.SYSTEM; break;
        }

        const entry: LogEntry = {
            id: Math.random().toString(36),
            time,
            turn: Math.floor(this.battleTime * 10),
            agentId: agent?.id || 'SYSTEM',
            team: agent?.team,
            location: agent ? `(${agent.q},${agent.r})` : 'global',
            actionType: type,
            actionName: actionName,
            targetInfo: targetInfo || '',
            detail: detail,
            visualColor: color,
            action: actionName,
            target: targetInfo || '',
            loc: agent ? `@(${agent.q},${agent.r})` : ''
        };

        this.logs.push(entry);
        if (this.logs.length > 2000) this.logs.shift();
    }
}

import { GameEngine } from "../game";
import { SCENE_DB } from "../../data/scenes";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../constants";
import { MovementType, GroundHazard, Team } from "../../types";
import { OBSTACLE_DB } from "../../data/obstacles";

export class MapSystem {
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();

    public obstacles: Map<string, string> = new Map();
    public obstaclesHash: Set<number> = new Set();

    private _heightMap: Map<string, number> = new Map();

    // Changed to Public for CombatSystem access
    public hazards: Map<string, GroundHazard> = new Map();

    constructor() {}

    public getTerrainHeight(q: number, r: number): number {
        return this._heightMap.get(HexUtils.key({q, r})) || 0;
    }

    public randomizeEnvironment(engine: GameEngine) {
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4); 
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuildMap(engine);
    }

    public rebuildMap(engine: GameEngine) {
        this.hazards.clear(); 

        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this._heightMap.clear();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tempHeights = new Map<string, number>();

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const hex = HexUtils.offsetToAxial(q, r, engine.mapConfig);
                const k = HexUtils.key(hex);

                this.mapKeys.add(k);
                this.validHashes.add(HexUtils.hash(hex.q, hex.r));

                const depthProgress = r / H; 
                const viewFactor = 1.0 - depthProgress; 
                const noise = Math.random();
                let rawHeight = 0;

                if (depthProgress > 0.7) {
                    rawHeight = noise * 0.8; 
                } else {
                    rawHeight = noise * (1.5 + viewFactor * 3.5);
                }

                tempHeights.set(k, rawHeight);
            }
        }

        const smoothedHeights = new Map<string, number>();
        tempHeights.forEach((h, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = h;
            let count = 1;
            sum += h; count++;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tempHeights.has(nk)) {
                    sum += tempHeights.get(nk)!;
                    count++;
                }
            });
            smoothedHeights.set(key, sum / count);
        });

        smoothedHeights.forEach((raw, key) => {
            let tier = Math.floor(raw);
            tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));
            this._heightMap.set(key, tier * BLOCK_HEIGHT);
        });

        this.pruneDisconnected(engine);
        this.generateDecorations(engine);

        engine.mapVersion++;
        if (engine.renderer) {
            engine.renderer.grid.reset();
        }
    }

    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number
    ) {
        if (!this.isValid(q, r)) return;
        const key = HexUtils.key({q, r});

        const hazard: GroundHazard = {
            id: Math.random().toString(36).substr(2, 6),
            q, r,
            type,
            duration,
            sourceId,
            team,
            color,
            power,
            interval,
            timer: 0 
        };

        this.hazards.set(key, hazard);
    }

    public getHazardAt(q: number, r: number): GroundHazard | undefined {
        return this.hazards.get(HexUtils.key({q, r}));
    }

    public tickHazards(dt: number, engine: GameEngine) {
        for (const [key, h] of this.hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt;

            if (h.duration <= 0) {
                this.hazards.delete(key);
                continue;
            }
        }
    }

    private generateDecorations(engine: GameEngine) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        this._heightMap.forEach((hPx, key) => {
            const [q, r] = key.split(',').map(Number);
            if (engine.getAgentAt(q, r)) return;
            const myTier = hPx / BLOCK_HEIGHT;
            const hex = {q, r};
            const neighbors = HexUtils.neighbors(hex);
            let isCliffBottom = false;
            let isFlatHigh = true;
            let validNeighbors = 0;
            neighbors.forEach(n => {
                if (!this.isValid(n.q, n.r)) return;
                validNeighbors++;
                const nH = this.getTerrainHeight(n.q, n.r);
                const nTier = nH / BLOCK_HEIGHT;
                if (nTier > myTier + 1) isCliffBottom = true;
                if (Math.abs(nTier - myTier) > 0.5) isFlatHigh = false;
            });
            if (isCliffBottom) {
                if (Math.random() < 0.7) {
                    this.setObstacle(q, r, obstacleType);
                    return;
                }
            }
            if (validNeighbors < 6) {
                if (Math.random() < 0.3) {
                    this.setObstacle(q, r, obstacleType);
                    return;
                }
            }
            if (myTier >= 2 && isFlatHigh) {
                if (Math.random() < 0.25) {
                    const type = engine.currentScene.textureType === 'FOREST' ? 'TREE' : obstacleType;
                    this.setObstacle(q, r, type);
                }
            }
        });
    }

    private pruneDisconnected(engine: GameEngine) {
        if (this.validHashes.size === 0) return;
        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const centerHex = HexUtils.offsetToAxial(centerQ, centerR, engine.mapConfig);
        let seed = HexUtils.hash(centerHex.q, centerHex.r);
        if (!this.validHashes.has(seed)) {
            seed = this.validHashes.values().next().value;
        }
        const reachable = new Set<number>();
        const queue: number[] = [seed];
        reachable.add(seed);
        let head = 0;
        while(head < queue.length) {
            const currentHash = queue[head++];
            const current = HexUtils.unhash(currentHash);
            const neighbors = HexUtils.neighbors(current);
            for (const n of neighbors) {
                const nHash = HexUtils.hash(n.q, n.r);
                if (this.validHashes.has(nHash) && !reachable.has(nHash)) {
                    reachable.add(nHash);
                    queue.push(nHash);
                }
            }
        }
        const toRemove: number[] = [];
        this.validHashes.forEach(h => {
            if (!reachable.has(h)) toRemove.push(h);
        });
        toRemove.forEach(h => {
            this.validHashes.delete(h);
            const hex = HexUtils.unhash(h);
            const k = HexUtils.key(hex);
            this.mapKeys.delete(k);
            this._heightMap.delete(k); 
        });
    }

    public setObstacle(q: number, r: number, type: string) {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.set(k, type);
        this.obstaclesHash.add(h);
    }

    public removeObstacle(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }

    public toggleObstacle(q: number, r: number, engine: GameEngine, type: string = 'WALL') {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!engine.getAgentAt(q, r)) {
                this.obstacles.set(k, type);
                this.obstaclesHash.add(h);
            }
        }
    }

    public isValid(q: number, r: number) { 
        return this.validHashes.has(HexUtils.hash(q, r));
    }

    public isValidHash(h: number) {
        return this.validHashes.has(h);
    }

    public hasObstacle(q: number, r: number) {
        return this.obstaclesHash.has(HexUtils.hash(q, r));
    }

    public hasObstacleHash(h: number) {
        return this.obstaclesHash.has(h);
    }

    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null, movementType: MovementType = MovementType.GROUND) { 
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) {
            const obsId = this.obstacles.get(HexUtils.key({q, r}));
            if (obsId) {
                const def = OBSTACLE_DB[obsId];
                if (def) {
                    if (movementType === MovementType.FLYING) {
                        if (def.blocksFlying) return true;
                    } else {
                        if (def.blocksMovement) return true;
                    }
                } else {
                    return true; 
                }
            } else {
                return true;
            }
        }
        const occupant = engine.agentMap.get(h);
        if (occupant) {
            if (occupant.id === ignoreId) return false;
            if (occupant.hp <= 0 || occupant.banished) return false;
            return true;
        }
        return engine.agents.some(a => {
            if (a.id === ignoreId) return false;
            if (!a.isMoving || a.path.length === 0) return false;
            const dest = a.path[0];
            return dest.q === q && dest.r === r;
        });
    }
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET, THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// Modular Spawners
import * as Generic from "../vfx/spawners/generic";
import * as Imperial from "../vfx/spawners/imperial";
import * as Covenant from "../vfx/spawners/covenant";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // IMPERIAL (BLUE)
                    if (id === 'tb_u1') { Imperial.spawnImperialSanctuary(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'tb_u2') { Imperial.spawnImperialKingsBlessing(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'wb_u1') { Imperial.spawnImperialThunder(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'wb_u2') { Imperial.spawnImperialDaybreak(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'rb_u1') { Imperial.spawnImperialCrystalArrow(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rb_u2') { Imperial.spawnImperialStarfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }
                    if (id === 'mb_u1') { Imperial.spawnImperialBlackHole(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'mb_u2') { Imperial.spawnImperialFrostfall(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'sb_u1') { Imperial.spawnImperialIntervention(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sb_u2') { Imperial.spawnImperialResurrection(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.4); return; }

                    // COVENANT (RED)
                    if (id === 'tr_u1') { Covenant.spawnCovenantGuillotine(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'tr_u2') { Covenant.spawnCovenantUndeadArmy(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.5); return; }
                    if (id === 'wr_u1') { Covenant.spawnCovenantRagnarok(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.9); return; }
                    if (id === 'wr_u2') { Covenant.spawnCovenantBloodStorm(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.6); return; }
                    if (id === 'rr_u1') { Covenant.spawnCovenantRailgun(vfx, event.pos.x - 200, event.pos.y, event.pos.x, event.pos.y, color); camera.addTrauma(0.8); return; }
                    if (id === 'rr_u2') { Covenant.spawnCovenantNuke(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.8); return; }
                    if (id === 'mr_u1') { Covenant.spawnCovenantMeteor(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.7); return; }
                    if (id === 'mr_u2') { Covenant.spawnCovenantDeathFinger(vfx, event.pos.x, event.pos.y - 200, event.pos.x, event.pos.y, color); camera.addTrauma(0.7); return; }
                    if (id === 'sr_u1') { Covenant.spawnCovenantSoulLink(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }
                    if (id === 'sr_u2') { Covenant.spawnCovenantAncestors(vfx, event.pos.x, visualGroundY, color); camera.addTrauma(0.3); return; }

                    // Generic Grid Reaction (Ground Cracks/Fields)
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            Generic.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // Generic Fallback
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    const hitColor = event.skill?.color || '#fff';
                    Generic.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    const vx = dAgent.physics.vx || 0;
                    const vy = dAgent.physics.vy || 0;
                    Generic.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role, vx, vy);
                }
                camera.addTrauma(0.15); 
                break;

            case 'SPAWN':
                Generic.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                Generic.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                Generic.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                if (event.skill?.id === 'mr_u2') {
                    Generic.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                Generic.spawnBeam(vfx, source.px, source.py - sH - 40, 0, event.pos.x, visualGroundY - 30, 0, event.color || '#fff');
                Generic.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    // NEW: Color coding based on VICTIM TEAM
                    // Blue Team = Blue chips/blood
                    // Red Team = Red chips/blood
                    const isVictimBlue = t.team === Team.BLUE;
                    const debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;

                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, debrisColor);
                }
            }
        } else {
            // Unknown source (e.g. DoT tick)
            Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualGroundY, 20, 0, -1, event.color || '#94a3b8');
        }

        if (dmg > 50) camera.addTrauma(0.05); 
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            if (skill && skill.id === 'mr_u2') {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                Generic.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                Generic.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; 
            }

            if (faction === Team.BLUE) {
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.5, 0.8, 'SPARK');
                Generic.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                Generic.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok Hit
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                Generic.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } 

        } else {
            // Standard Hit Logic
            let dx = 0, dy = 0;
            let debrisColor = color; 

            if (event.targetId) {
                const t = engine.agents.find(a => a.id === event.targetId);
                if (t) {
                    const isVictimBlue = t.team === Team.BLUE;
                    debrisColor = isVictimBlue ? THEME_IMPERIAL.energy : THEME_COVENANT.secondary;
                }
            }

            if (source) {
                const len = Math.sqrt((event.pos.x - source.px)**2 + (event.pos.y - source.py)**2) || 1;
                dx = (event.pos.x - source.px) / len;
                dy = (event.pos.y - source.py) / len;
            }

            if (visualType === 'SMASH') {
                Generic.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Smash creates heavy splatter using VICTIM color
                Generic.spawnPhysicsSplatter(vfx, event.pos.x, centerVisualY, 10, dx, dy, debrisColor);
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                Generic.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                Generic.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                // Magic Bolt / Arrow
                // FIX: 'RING' was not rendered by ParticleRenderer. Swapped to 'SHOCKWAVE'.
                Generic.addImpact(vfx, event.pos.x, visualY, 30, color, 'SHOCKWAVE', 0.4);
                if (dx !== 0 || dy !== 0) {
                    Generic.spawnPhysicsSplatter(vfx, event.pos.x, visualY, 30, dx, dy, debrisColor);
                } else {
                    Generic.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
                }
            }
        }
    }
}

export interface Particle {
    active: boolean; // Pooling flag
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    rotation: number;     // Current rotation
    vRotation: number;    // Rotation speed
    life: number;
    maxLife: number;
    color: string;
    size: number;
    // Consolidated Types for Simplicity
    // Added ROCK for heavy debris
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK';
    targetX?: number; // For BEAM
    targetY?: number; // For BEAM
    delay?: number;
    image?: HTMLCanvasElement; // For SPRITE type (Unit parts)
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            p.active = true;
            p.image = undefined; // Reset image reference
            p.delay = 0; // Reset delay
            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#fff', size: 0, type: 'SPARK',
            delay: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        // Return active particles to pool immediately
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXSystem } from "../vfx";
import { spawnExplosion, spawnShockwave, addImpact, spawnBeam, spawnLingeringField } from "./generic";

// =========================================================================================
// 🔵 IMPERIAL (BLUE) - ULTRAMARINES THEME
// Keywords: Order, Tactical, Orbital Bombardment, Bolter Fire, Golden Light
// =========================================================================================

// 🛡️ TANK: FORTRESS OF HERA (tb_u1)
// "Sanctuary" -> Defensive Pylons.
export function spawnImperialSanctuary(system: VFXSystem, x: number, y: number, color: string) {
    const radius = 160;

    // 1. Central Aquila Beacon
    const beacon = system.state.getParticle();
    beacon.x = x; beacon.y = y; beacon.z = 0;
    beacon.life = 3.0; beacon.maxLife = 3.0;
    beacon.color = '#fbbf24'; // Gold
    beacon.size = 40; // Wider
    beacon.type = 'PILLAR'; 
    system.state.particles.push(beacon);

    // 2. Perimeter Shield Drones
    for(let i=0; i<6; i++) {
        const angle = (i / 6) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Laser fence
        const fence = system.state.getParticle();
        fence.x = px; fence.y = py; fence.z = 10;
        fence.targetX = x; fence.targetY = y;
        fence.life = 3.0; fence.maxLife = 3.0;
        fence.color = '#3b82f6';
        fence.size = 2; // Thicker
        fence.type = 'BEAM';
        system.state.particles.push(fence);
    }
}

// 🛡️ TANK: THE EMPEROR'S LIGHT (tb_u2)
// "Kings Blessing" -> Massive Holy Pillar
export function spawnImperialKingsBlessing(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Massive Shaft of Light
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 2.0; beam.maxLife = 2.0;
    beam.color = '#fcd34d';
    beam.size = 80; // HUGE
    beam.type = 'PILLAR';
    system.state.particles.push(beam);

    // 2. Ascending Particles
    spawnExplosion(system, x, y, 0, 20, '#fff', 5.0, 2.0, 'GLOW');
}

// ⚔️ WARRIOR: ORBITAL STRIKE (wb_u1)
// "Thunder" -> Ion Cannon Strike
export function spawnImperialThunder(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Ion Beam
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 0.5; beam.maxLife = 0.5; // Short, intense
    beam.color = '#60a5fa'; // Plasma Blue
    beam.size = 120; // Massive width
    beam.type = 'PILLAR';
    system.state.particles.push(beam);

    // 2. Ground Debris
    spawnExplosion(system, x, y, 0, 15, '#1e3a8a', 3.0, 0.8, 'DEBRIS'); 

    // 3. Shockwave
    spawnShockwave(system, x, y, '#93c5fd', 0.8);
}

// ⚔️ WARRIOR: EXTERMINATUS (wb_u2)
// "Daybreak" -> Sun Bomb
export function spawnImperialDaybreak(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Central Nova
    spawnExplosion(system, x, y, 10, 30, '#f59e0b', 4.0, 1.0, 'SPARK');
    addImpact(system, x, y, 20, '#fbbf24', 'BLAST', 1.0);

    // 2. Rising Pillar
    const beam = system.state.getParticle();
    beam.x = x; beam.y = y; beam.z = 0;
    beam.life = 1.0; beam.maxLife = 1.0;
    beam.color = '#fffbeb';
    beam.size = 150;
    beam.type = 'PILLAR';
    system.state.particles.push(beam);
}

// 🏹 RANGER: BOLTER VOLLEY (rb_u1)
export function spawnImperialCrystalArrow(system: VFXSystem, x: number, y: number, color: string) {
    for(let i=0; i<5; i++) {
        setTimeout(() => {
            const ox = (Math.random()-0.5) * 60;
            const oy = (Math.random()-0.5) * 60;
            spawnExplosion(system, x+ox, y+oy, 20, 8, '#facc15', 1.5, 0.4, 'SPARK');
            spawnExplosion(system, x+ox, y+oy, 20, 5, '#1e293b', 0.8, 0.8, 'SMOKE');
        }, i * 80);
    }
}

// 🏹 RANGER: DROP POD ASSAULT (rb_u2)
export function spawnImperialStarfall(system: VFXSystem, x: number, y: number, color: string) {
    const count = 6;
    const radius = 180;

    for(let i=0; i<count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const px = x + Math.cos(angle) * radius;
        const py = y + Math.sin(angle) * radius;

        // Pod Trail
        const pod = system.state.getParticle();
        pod.x = px; pod.y = py; pod.z = 1000;
        pod.vx = 0; pod.vy = 0; pod.vz = -2500; 
        pod.life = 0.4; pod.maxLife = 0.4;
        pod.color = '#fcd34d'; // Burning entry
        pod.size = 25;
        pod.type = 'DEBRIS'; 
        pod.delay = i * 0.1;
        system.state.particles.push(pod);

        // Impact
        setTimeout(() => {
            spawnExplosion(system, px, py, 0, 12, '#94a3b8', 1.5, 0.6, 'DEBRIS');
            addImpact(system, px, py, 0, '#fff', 'BLAST', 0.4);
        }, 400 + (i * 100));
    }
}

